import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/k8s/context.html","title":"","lang":"en-US","frontmatter":{},"git":{"updatedTime":1746702087000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":2,"url":"https://github.com/hifat"}],"changelog":[{"hash":"01f74816b0e1a39e659ca1ed7646072c3579afbc","time":1746702087000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add k8s context"},{"hash":"a0b36268f7f50551d4998fa73cf308dd4ee7fd4d","time":1746687460000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add k8s context"}]},"filePathRelative":"k8s/context.md"}`),a={name:`context.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h2 id="context" tabindex="-1"><a class="header-anchor" href="#context"><span>Context</span></a></h2><hr><p>🔵 <code>kubectl config get-contexts</code></p><p>คือ: สั่งให้ Kubernetes CLI (kubectl) โชว์ รายการ contexts ที่มีอยู่ในเครื่องเรา</p><p>Context คือ เซ็ตข้อมูลประกอบด้วย:</p><ul><li>Cluster → ต่อไปที่ไหน (เช่น Minikube, GKE, EKS, Docker Desktop ฯลฯ)</li><li>User → ใครล็อกอินอยู่</li><li>Namespace → Default namespace ที่จะใช้ถ้าไม่ระบุ</li></ul><p>สรุปง่าย ๆ: context = บอกว่า ตอนนี้ “จะต่อไปที่ cluster ไหน ด้วย user ไหน บน namespace อะไร”</p><p>เวลาใช้ kubectl config get-contexts จะเห็นตารางแบบนี้:</p><table><thead><tr><th>CURRENT</th><th>NAME</th><th>CLUSTER</th><th>AUTHINFO</th><th>NAMESPACE</th></tr></thead><tbody><tr><td>*</td><td>docker-desktop</td><td>docker-desktop</td><td>docker-desktop</td><td>default</td></tr></tbody></table><ul><li>เครื่องหมาย * = ตัวที่ “active” อยู่ตอนนี้</li><li>เช่น ในตัวอย่างด้านบน → ตอนนี้เราเชื่อมต่อกับ cluster “docker-desktop” อยู่</li></ul><hr><p>🔵 <code>kubectl config set-context docker-desktop</code></p><p>คือ: สั่งให้ kubectl ตั้งค่า “context ปัจจุบัน” ไปที่ docker-desktop</p><p>จริง ๆ เต็ม ๆ คือ</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">kubectl</span><span style="color:#9ECBFF;"> config</span><span style="color:#9ECBFF;"> use-context</span><span style="color:#9ECBFF;"> docker-desktop\`</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ไม่ใช่ set-context นะ!</p><hr><p>🔥 ความแตกต่างสำคัญ:</p><table><thead><tr><th>คำสั่ง</th><th>ทำอะไร</th></tr></thead><tbody><tr><td>get-contexts</td><td>โชว์ context ที่มีในเครื่อง</td></tr><tr><td>use-context</td><td>เปลี่ยน context ที่ใช้อยู่ตอนนี้</td></tr><tr><td>set-context</td><td>(ตั้งค่า) กำหนดข้อมูลใหม่ให้ context ชื่อหนึ่ง เช่น ตั้ง namespace ใหม่</td></tr></tbody></table><p>สรุป:</p><ul><li>ถ้าแค่ “เปลี่ยน” ไปใช้ docker-desktop → ต้องใช้ kubectl config use-context docker-desktop</li><li>ถ้า “แก้” properties ของ context docker-desktop → ใช้ kubectl config set-context docker-desktop</li></ul><p>ตัวอย่าง set-context:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">kubectl</span><span style="color:#9ECBFF;"> config</span><span style="color:#9ECBFF;"> set-context</span><span style="color:#9ECBFF;"> docker-desktop</span><span style="color:#79B8FF;"> --namespace=my-namespace</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>= ตั้ง namespace default ของ context docker-desktop เป็น my-namespace</p><hr><p>🧠 สรุปรวมอีกทีแบบรวบรัด:</p><table><thead><tr><th>คำสั่ง</th><th>สรุปสั้นสุด</th></tr></thead><tbody><tr><td>kubectl config get-contexts</td><td>ดู context ทั้งหมดในเครื่อง</td></tr><tr><td>kubectl config use-context docker-desktop</td><td>เปลี่ยนไปใช้ context docker-desktop</td></tr><tr><td>kubectl config set-context docker-desktop --namespace=x</td><td>ตั้ง namespace ของ docker-desktop เป็น x</td></tr></tbody></table><hr><h3 id="trip" tabindex="-1"><a class="header-anchor" href="#trip"><span>Trip</span></a></h3><ul><li>Add gcp context</li></ul><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">gcloud</span><span style="color:#9ECBFF;"> container</span><span style="color:#9ECBFF;"> clusters</span><span style="color:#9ECBFF;"> get-credentials</span><span style="color:#9ECBFF;"> hello-sekai-shop-ms</span><span style="color:#79B8FF;"> --z</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">one</span><span style="color:#9ECBFF;"> australia-southeast1-b</span><span style="color:#79B8FF;"> --project</span><span style="color:#9ECBFF;"> hello-sekai-shop-ms</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,31)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};